Step 6: Service 계층에서 사용
package com.example.service
import com.example.domain.User
import com.example.repository.UserRepository
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
@Service
class UserService(
private val userRepository: UserRepository
) {
/**
* 사용자 생성
* createdAt, createdBy가 자동으로 설정됨
*/
@Transactional
fun createUser(name: String, email: String, age: Int): User {
val user = User(
name = name,
email = email,
age = age
)
return userRepository.save(user)
// 저장 시 자동으로:
// - createdAt = 현재 시각
// - createdBy = "admin" (현재 로그인 사용자)
// - updatedAt = 현재 시각
// - updatedBy = "admin"
}
/**
* 사용자 수정
* updatedAt, updatedBy가 자동으로 갱신됨
*/
@Transactional
fun updateUser(id: String, name: String): User {
val user = userRepository.findById(id)
.orElseThrow { IllegalArgumentException("User not found") }
val updated = user.copy(name = name)
return userRepository.save(updated)
// 저장 시 자동으로:
// - updatedAt = 현재 시각 (갱신)
// - updatedBy = "admin" (갱신)
// - createdAt, createdBy는 유지
}
}
Step 7: 테스트 코드로 검증
package com.example.service
import com.example.domain.User
import com.example.repository.UserRepository
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.security.test.context.support.WithMockUser
import org.springframework.transaction.annotation.Transactional
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue
@SpringBootTest
@Transactional
class UserServiceTest {
@Autowired
private lateinit var userService: UserService
@Autowired
private lateinit var userRepository: UserRepository
@Test
@WithMockUser(username = "testuser")
fun `사용자 생성 시 Audit 정보가 자동으로 기록되는지 테스트`() {
// given
val name = "김철수"
val email = "test@example.com"
val age = 30
// when
val savedUser = userService.createUser(name, email, age)
// then
assertNotNull(savedUser.id)
assertNotNull(savedUser.createdAt)
assertNotNull(savedUser.createdBy)
assertNotNull(savedUser.updatedAt)
assertNotNull(savedUser.updatedBy)
assertEquals("testuser", savedUser.createdBy)
assertEquals("testuser", savedUser.updatedBy)
println("✅ 생성일시: ${savedUser.createdAt}")
println("✅ 생성자: ${savedUser.createdBy}")
}
@Test
@WithMockUser(username = "admin")
fun `사용자 수정 시 updatedAt과 updatedBy만 갱신되는지 테스트`() {
// given
val user = userRepository.save(
User(name = "이영희", email = "lee@example.com", age = 25)
)
val originalCreatedAt = user.createdAt
val originalCreatedBy = user.createdBy
Thread.sleep(100) // 시간 차이를 두기 위해
// when
val updatedUser = userService.updateUser(user.id!!, "이영희2")
// then
assertEquals(originalCreatedAt, updatedUser.createdAt) // 생성일시 유지
assertEquals(originalCreatedBy, updatedUser.createdBy) // 생성자 유지
assertTrue(updatedUser.updatedAt!! > originalCreatedAt!!) // 수정일시 갱신
assertEquals("admin", updatedUser.updatedBy) // 수정자 갱신
println("✅ 생성일시 유지: ${updatedUser.createdAt}")
println("✅ 수정일시 갱신: ${updatedUser.updatedAt}")
println("✅ 수정자: ${updatedUser.updatedBy}")
}
}
📸 이미지 3: 테스트 실행 결과 스크린샷
4. 트러블슈팅 - 자주 겪는 문제들
❌ 문제 1: createdAt이 null로 저장됨
증상:
val user = userRepository.save(User(name = "김철수", ...))
println(user.createdAt) // null 출력 😱
원인: @EnableMongoAuditing을 설정하지 않음
해결:
@Configuration
@EnableMongoAuditing // ✅ 이 어노테이션 추가!
class MongoAuditConfig {
// ...
}
❌ 문제 2: createdBy가 항상 "system"으로만 저장됨
증상:
// 로그인 사용자가 "admin"인데...
val user = userRepository.save(User(...))
println(user.createdBy) // "system" 출력 😱
원인: AuditorAware Bean을 등록하지 않았거나, Spring Security 인증 정보를 제대로 가져오지 못함
해결:
@Bean
fun auditorProvider(): AuditorAware<String> {
return AuditorAware {
val auth = SecurityContextHolder.getContext().authentication
// 디버깅용 로그 추가
println("현재 인증 정보: ${auth?.name}")
if (auth != null && auth.isAuthenticated && auth.name != "anonymousUser") {
Optional.of(auth.name)
} else {
Optional.of("system")
}
}
}
❌ 문제 3: updatedAt이 갱신되지 않음
증상:
val user = userRepository.findById("123").get()
val updated = user.copy(name = "새이름")
userRepository.save(updated)
// updatedAt이 변경 안 됨! 😱
원인: Kotlin data class의 copy()는 새 인스턴스를 생성하는데, Audit 필드가 val로 선언됨
해결:
// ❌ 나쁜 예
abstract class BaseEntity(
@CreatedDate
val createdAt: LocalDateTime? = null, // val로 선언
@LastModifiedDate
val updatedAt: LocalDateTime? = null // val로 선언
)
// ✅ 좋은 예
abstract class BaseEntity(
@CreatedDate
var createdAt: LocalDateTime? = null, // var로 선언!
@LastModifiedDate
var updatedAt: LocalDateTime? = null // var로 선언!
)
❌ 문제 4: @Transactional 없이 save()를 여러 번 호출할 때
증상:
fun complexOperation() {
val user = userRepository.save(User(...)) // 첫 save
// 다른 작업...
val updated = user.copy(name = "수정")
userRepository.save(updated) // 두 번째 save
// updatedBy가 첫 번째 사용자로 남아있음 😱
}
해결:
@Transactional // ✅ 트랜잭션 추가
fun complexOperation() {
// ...
}
